-- Reviewed TMDB/Metron hero catalog, fetched 2026-10-03. No network during deploy.
-- 119 new works; existing aggregate works retain identity, dates and diary progress.
CREATE TEMP TABLE hero_publication(entry jsonb) ON COMMIT DROP;
DO $publish$
DECLARE e jsonb; item text; uni text; sid text; m jsonb; p jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock(72451902);
  FOR e IN SELECT entry FROM hero_publication LOOP
    item := e->>'suggestedItemId'; p := e->'publication'; m := e->'metadata'; uni := p->>'universe';
    IF EXISTS (SELECT 1 FROM catalog_sources s WHERE s.provider=e->>'provider'
      AND (s.external_id=e->>'externalId' OR s.item_id=item)
      AND NOT(s.external_id=e->>'externalId' AND s.item_id=item)) THEN
      RAISE EXCEPTION 'CATALOG_MAPPING_CONFLICT';
    END IF;
    IF (p->>'existing')::boolean THEN
      IF NOT EXISTS(SELECT 1 FROM catalog_items i WHERE i.id=item AND i.universe_id=uni AND i.type=e->>'type') THEN
        RAISE EXCEPTION 'CATALOG_MAPPING_CONFLICT';
      END IF;
    ELSE
      IF EXISTS(SELECT 1 FROM catalog_items WHERE id=item) AND NOT EXISTS(
        SELECT 1 FROM catalog_items i JOIN catalog_sources s ON s.item_id=i.id
        WHERE i.id=item AND i.universe_id=uni AND i.type=e->>'type'
          AND s.provider=e->>'provider' AND s.external_id=e->>'externalId') THEN
        RAISE EXCEPTION 'CATALOG_MAPPING_CONFLICT';
      END IF;
    END IF;
    IF NOT (p->>'artworkOnly')::boolean THEN
        SELECT item,locale,m->'titles'->>locale,m->>'year',m->'descriptions'->>locale,'—'
        FROM unnest(ARRAY['pt-BR','en']) locale ON CONFLICT(item_id,locale) DO NOTHING;
    END IF;
    IF jsonb_typeof(p->'issue')='object' AND NOT (p->>'artworkOnly')::boolean THEN
      sid := 'metron-' || (p->'issue'->>'seriesID');
      IF NOT EXISTS(SELECT 1 FROM catalog_series WHERE id=sid AND universe_id=uni AND year=(p->'issue'->>'year')::int) THEN
        RAISE EXCEPTION 'CATALOG_MAPPING_CONFLICT';
      END IF;
        VALUES(sid,'pt-BR',p->'issue'->>'seriesPT'),(sid,'en',p->'issue'->>'series') ON CONFLICT(series_id,locale) DO NOTHING;
        VALUES(item,sid,p->'issue'->>'number',(p->'issue'->>'number')::int) ON CONFLICT(item_id) DO NOTHING;
      IF NOT EXISTS(SELECT 1 FROM catalog_series_items WHERE item_id=item AND series_id=sid
        AND issue_number=p->'issue'->>'number' AND position=(p->'issue'->>'number')::int) THEN
        RAISE EXCEPTION 'CATALOG_MAPPING_CONFLICT';
      END IF;
    END IF;
      VALUES(e->>'provider',e->>'externalId',item,e->>'sourceUrl',
        (extract(epoch FROM (e->>'fetchedAt')::timestamptz)*1000)::bigint,
        m || jsonb_build_object('attribution',e->'attribution'),(e->>'fetchedAt')::timestamptz)
      ON CONFLICT(provider,external_id) DO UPDATE SET source_url=EXCLUDED.source_url,revision=EXCLUDED.revision,
        metadata=EXCLUDED.metadata,fetched_at=EXCLUDED.fetched_at
        WHERE catalog_sources.item_id=EXCLUDED.item_id AND catalog_sources.fetched_at<EXCLUDED.fetched_at;
  END LOOP;
END $publish$;
