('{"provider":"tmdb","externalId":"movie:155","suggestedItemId":"d-tdk","kind":"movie","type":"Filme","sourceUrl":"https://www.themoviedb.org/movie/155","fetchedAt":"2026-10-03T18:02:39.544Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"The Dark Knight","pt-BR":"Batman: O Cavaleiro das Trevas"},"descriptions":{"en":"Batman raises the stakes in his war on crime. With the help of Lt. Jim Gordon and District Attorney Harvey Dent, Batman sets out to dismantle the remaining criminal organizations that plague the streets. The partnership proves to be effective, but they soon find themselves prey to a reign of chaos unleashed by a rising criminal mastermind known to the terrified citizens of Gotham as the Joker.","pt-BR":"Após dois anos desde o surgimento do Batman, os criminosos de Gotham City têm muito o que temer. Com a ajuda do tenente James Gordon e do promotor público Harvey Dent, Batman luta contra o crime organizado. Acuados com o combate, os chefes do crime aceitam a proposta feita pelo Coringa e o contratam para combater o Homem-Morcego."},"year":"2008","originalLanguage":"en","genres":["Action","Thriller","Crime"],"cast":[{"id":3894,"name":"Christian Bale","character":"Bruce Wayne"},{"id":1810,"name":"Heath Ledger","character":"Joker"},{"id":6383,"name":"Aaron Eckhart","character":"Harvey Dent"},{"id":3895,"name":"Michael Caine","character":"Alfred"},{"id":1579,"name":"Maggie Gyllenhaal","character":"Rachel"},{"id":64,"name":"Gary Oldman","character":"Gordon"},{"id":192,"name":"Morgan Freeman","character":"Lucius Fox"},{"id":53651,"name":"Monique Gabriela Curnen","character":"Ramirez"},{"id":57597,"name":"Ron Dean","character":"Wuertz"},{"id":2037,"name":"Cillian Murphy","character":"Scarecrow"},{"id":101015,"name":"Chin Han","character":"Lau"},{"id":21316,"name":"Nestor Carbonell","character":"Mayor"},{"id":21315,"name":"Eric Roberts","character":"Maroni"},{"i