('{"provider":"tmdb","externalId":"movie:272","suggestedItemId":"d-tmdb-movie-272","kind":"movie","type":"Filme","sourceUrl":"https://www.themoviedb.org/movie/272","fetchedAt":"2026-10-03T18:02:39.544Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"Batman Begins","pt-BR":"Batman Begins"},"descriptions":{"en":"Driven by tragedy, billionaire Bruce Wayne dedicates his life to uncovering and defeating the corruption that plagues his home, Gotham City. Unable to work within the system, he instead creates a new identity, a symbol of fear for the criminal underworld - The Batman.","pt-BR":"Marcado pelo assassinato de seus pais quando ainda era criança, o milionário Bruce Wayne decide viajar pelo mundo em busca de encontrar meios que lhe permitam combater a injustiça e provocar medo em seus adversários. Após retornar a Gotham City, sua cidade-natal, ele idealiza seu alter-ego: Batman, um justiceiro mascarado que usa força, inteligência e um arsenal tecnológico para combater o crime."},"year":"2005","originalLanguage":"en","genres":["Drama","Crime","Action"],"cast":[{"id":3894,"name":"Christian Bale","character":"Bruce Wayne / Batman"},{"id":3895,"name":"Michael Caine","character":"Alfred"},{"id":3896,"name":"Liam Neeson","character":"Ducard"},{"id":3897,"name":"Katie Holmes","character":"Rachel Dawes"},{"id":64,"name":"Gary Oldman","character":"Jim Gordon"},{"id":2037,"name":"Cillian Murphy","character":"Dr. Jonathan Crane"},{"id":207,"name":"Tom Wilkinson","character":"Carmine Falcone"},{"id":585,"name":"Rutger Hauer","character":"Earle"},{"id":3899,"name":"Ken Watanabe","character":"Ra''s al Ghul"},{"id":534,"name":"Mark Boone Junior","character":"Flass"},{"id":3900,"name":"Linus Roache","character":"Thomas Wayne"},{"id":192,"name":"Morgan Freeman","character":"Lucius Fox"},{"id":544,"name":"Larry Holden","character":"Finch"},{"id":151943,"name":"Gerard Murphy","character