('{"provider":"tmdb","externalId":"movie:49026","suggestedItemId":"d-tmdb-movie-49026","kind":"movie","type":"Filme","sourceUrl":"https://www.themoviedb.org/movie/49026","fetchedAt":"2026-10-03T18:02:39.545Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"The Dark Knight Rises","pt-BR":"Batman: O Cavaleiro das Trevas Ressurge"},"descriptions":{"en":"Following the death of District Attorney Harvey Dent, Batman assumes responsibility for Dent''s crimes to protect the late attorney''s reputation and is subsequently hunted by the Gotham City Police Department. Eight years later, Batman encounters the mysterious Selina Kyle and the villainous Bane, a new terrorist leader who overwhelms Gotham''s finest. The Dark Knight resurfaces to protect a city that has branded him an enemy.","pt-BR":"Após ser culpado pela morte de Harvey Dent e passar de herói a vilão, Batman desaparece. As coisas mudam com a chegada de uma ladra misteriosa, a Mulher-Gato, e Bane, um terrorista mascarado, que fazem Batman abandonar seu exílio forçado."},"year":"2012","originalLanguage":"en","genres":["Action","Crime","Drama","Thriller"],"cast":[{"id":3894,"name":"Christian Bale","character":"Bruce Wayne"},{"id":64,"name":"Gary Oldman","character":"Commissioner Gordon"},{"id":2524,"name":"Tom Hardy","character":"Bane"},{"id":24045,"name":"Joseph Gordon-Levitt","character":"Blake"},{"id":1813,"name":"Anne Hathaway","character":"Selina"},{"id":8293,"name":"Marion Cotillard","character":"Miranda"},{"id":192,"name":"Morgan Freeman","character":"Fox"},{"id":3895,"name":"Michael Caine","character":"Alfred"},{"id":8654,"name":"Matthew Modine","character":"Foley"},{"id":16607,"name":"Alon Aboutboul","character":"Dr. Pavel"},{"id":77335,"name":"Ben Mendelsohn","character":"Daggett"},{"id":39659,"name":"Burn Gorman","character":"Stryver"},{"id":10582,"name":"Daniel Sunjata","character":"Captain Jones"},{"id":497