('{"provider":"tmdb","externalId":"movie:268","suggestedItemId":"d-tmdb-movie-268","kind":"movie","type":"Filme","sourceUrl":"https://www.themoviedb.org/movie/268","fetchedAt":"2026-10-03T18:02:39.545Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"Batman","pt-BR":"Batman"},"descriptions":{"en":"Having witnessed his parents'' brutal murder as a child, millionaire philanthropist Bruce Wayne fights crime in Gotham City disguised as Batman, a costumed hero who strikes fear into the hearts of villains. But when a deformed madman known as ''The Joker'' seizes control of Gotham''s criminal underworld, Batman must face his most ruthless nemesis ever while protecting both his identity and his love interest, reporter Vicki Vale.","pt-BR":"Em Gotham City o milionário Bruce Wayne, que quando jovem teve os pais assassinados por bandidos, resolve combater o crime como Batman, o Homem-Morcego. Mas chega o dia em que o vilão Coringa decide dominar a cidade e se torna um grande desafio para o super-herói."},"year":"1989","originalLanguage":"en","genres":["Fantasy","Action","Crime"],"cast":[{"id":2232,"name":"Michael Keaton","character":"Batman / Bruce Wayne"},{"id":514,"name":"Jack Nicholson","character":"Joker / Jack Napier"},{"id":326,"name":"Kim Basinger","character":"Vicki Vale"},{"id":4040,"name":"Robert Wuhl","character":"Alexander Knox"},{"id":3798,"name":"Pat Hingle","character":"Commissioner Gordon"},{"id":3799,"name":"Billy Dee Williams","character":"Harvey Dent"},{"id":3796,"name":"Michael Gough","character":"Alfred"},{"id":3785,"name":"Jack Palance","character":"Grissom"},{"id":3800,"name":"Jerry Hall","character":"Alicia"},{"id":3801,"name":"Tracey Walter","character":"Bob the Goon"},{"id":3802,"name":"Lee Wallace","character":"Mayor"},{"id":663,"name":"William Hootkins","character":"Eckhardt"},{"id":79502,"name":"Richard Strange","character":"Goon"},{"id":127166,"name