('{"provider":"tmdb","externalId":"movie:364","suggestedItemId":"d-tmdb-movie-364","kind":"movie","type":"Filme","sourceUrl":"https://www.themoviedb.org/movie/364","fetchedAt":"2026-10-03T18:02:39.545Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"Batman Returns","pt-BR":"Batman: O Retorno"},"descriptions":{"en":"The monstrous Penguin, who dwells in the sewers beneath Gotham, joins up with corrupt mayoral candidate Max Shreck to topple the Batman once and for all. But when Shreck''s timid assistant Selina Kyle finds out, and Shreck tries to kill her, she''s transformed into the sexy Catwoman. She teams up with the Penguin and Shreck to destroy Batman, but sparks fly unexpectedly when she confronts the caped crusader.","pt-BR":"O monstruoso Pinguim, que vive nos arredores de Gotham, se junta ao diabólico empresário Max Shreck para vencer Batman de uma vez por todas. Porém, a secretária de Shreck, Selina Kyle, descobre os planos e se transforma na irresistível Mulher Gato que se alia na destruição de Batman."},"year":"1992","originalLanguage":"en","genres":["Action","Fantasy"],"cast":[{"id":2232,"name":"Michael Keaton","character":"Batman / Bruce Wayne"},{"id":518,"name":"Danny DeVito","character":"Penguin"},{"id":1160,"name":"Michelle Pfeiffer","character":"Catwoman / Selina"},{"id":4690,"name":"Christopher Walken","character":"Max Shreck"},{"id":3796,"name":"Michael Gough","character":"Alfred"},{"id":3798,"name":"Pat Hingle","character":"Commissioner Gordon"},{"id":4776,"name":"Michael Murphy","character":"Mayor"},{"id":5130,"name":"Cristi Conaway","character":"Ice Princess"},{"id":52366,"name":"Andrew Bryniarski","character":"Chip"},{"id":3418,"name":"Vincent Schiavelli","character":"Organ Grinder"},{"id":152864,"name":"Steve Witting","character":"Josh"},{"id":129332,"name":"Jan Hooks","character":"Jen"},{"id":1961854,"name":"John Strong","character":"Sword Swallo