('{"provider":"tmdb","externalId":"movie:49521","suggestedItemId":"d-tmdb-movie-49521","kind":"movie","type":"Filme","sourceUrl":"https://www.themoviedb.org/movie/49521","fetchedAt":"2026-10-03T18:02:39.545Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"Man of Steel","pt-BR":"O Homem de Aço"},"descriptions":{"en":"A young boy learns that he has extraordinary powers and is not of this earth. As a young man, he journeys to discover where he came from and what he was sent here to do. But the hero in him must emerge if he is to save the world from annihilation and become the symbol of hope for all mankind.","pt-BR":"Um garoto descobre que não é deste planeta e que tem poderes extraordinários. Quando se torna adolescente, viaja para descobrir de onde veio e para o quê foi enviado a fazer. Mas o herói nele deve emergir se quiser salvar o mundo da aniquilação e se tornar o símbolo de esperança para toda a humanidade."},"year":"2013","originalLanguage":"en","genres":["Action","Adventure","Science Fiction"],"cast":[{"id":73968,"name":"Henry Cavill","character":"Clark Kent / Kal-El"},{"id":9273,"name":"Amy Adams","character":"Lois Lane"},{"id":335,"name":"Michael Shannon","character":"General Zod"},{"id":2882,"name":"Diane Lane","character":"Martha Kent"},{"id":934,"name":"Russell Crowe","character":"Jor-El"},{"id":43202,"name":"Antje Traue","character":"Faora-Ul"},{"id":9464,"name":"Harry Lennix","character":"General Swanwick"},{"id":31028,"name":"Richard Schiff","character":"Dr. Emil Hamilton"},{"id":22227,"name":"Christopher Meloni","character":"Colonel Nathan Hardy"},{"id":1269,"name":"Kevin Costner","character":"Jonathan Kent"},{"id":8786,"name":"Ayelet Zurer","character":"Lara Lor-Van"},{"id":2975,"name":"Laurence Fishburne","character":"Perry White"},{"id":213049,"name":"Jadin Gould","character":"Lana Lang"},{"id":236302,"name":"Dylan Sprayberry","character":"Clark Kent (13 Years)"},{"id":928574,"name":"Cooper Timberline","character":"Clark Kent (9 Years)"},{"id":12371,"name":"Richard Cetrone","character":"Tor-An"},{"id":37698,"name":"Mackenzie Gray","character":"Jax-Ur"},{"id":2320,"name":"Julian Richings","character":"Lor-Em"},{"id":11831,"name":"Mary Black","character":"Ro-Zar"},{"id":1272968,"name":"Samantha Win","character":"Car-Vex"}],"releaseDate":"2013-06-12","runtimeMinutes":143,"posterURL":"https://image.tmdb.org/t/p/w500/8GFtkImmK0K1VaUChR0n9O61CFU.jpg","creators":[{"id":15217,"name":"Zack Snyder","roles":["Director"]},{"id":3893,"name":"David S. Goyer","roles":["Screenplay"]},{"id":525,"name":"Christopher Nolan","roles":["Story"]},{"id":3893,"name":"David S. Goyer","roles":["Story"]}],"characters":[]},"publication":{"universe":"dc","artworkOnly":false,"existing":false}}'::jsonb),
('{"provider":"tmdb","externalId":"movie:209112","suggestedItemId":"d-tmdb-movie-209112","kind":"movie","type":"Filme","sourceUrl":"https://www.themoviedb.org/movie/209112","fetchedAt":"2026-10-03T18:02:39.545Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"Batman v Superman: Dawn of Justice","pt-BR":"Batman vs Superman: A Origem da Justiça"},"descriptions":{"en":"Fearing the actions of a god-like Super Hero left unchecked, Gotham City’s own formidable, forceful vigilante takes on Metropolis’s most revered, modern-day savior, while the world wrestles with what sort of hero it really needs. And with Batman and Superman at war with one another, a new threat quickly arises, putting mankind in greater danger than it’s ever known before.","pt-BR":"Temendo que as ações de um super-herói divino não tenham sido controladas, o formidável e vigoroso vigilante de Gotham City enfrenta o salvador mais reverenciado e moderno de Metrópolis, enquanto o mundo luta com o tipo de herói que realmente precisa. E com Batman e Superman em guerra um contra o outro, uma nova ameaça rapidamente surge, colocando a humanidade em maior perigo do que nunca antes."},"year":"2016","originalLanguage":"en","genres":["Action","Adventure","Fantasy"],"cast":[{"id":880,"name":"Ben Affleck","character":"Bruce Wayne / Batman"},{"id":73968,"name":"Henry Cavill","character":"Clark Kent / Superman"},{"id":44735,"name":"Jesse Eisenberg","character":"Lex Luthor"},{"id":90633,"name":"Gal Gadot","character":"Diana Prince / Wonder Woman"},{"id":9273,"name":"Amy Adams","character":"Lois"},{"id":2882,"name":"Diane Lane","character":"Martha Kent"},{"id":2975,"name":"Laurence Fishburne","character":"Perry White"},{"id":16940,"name":"Jeremy Irons","character":"Alfred"},{"id":18686,"name":"Holly Hunter","character":"Senator Finch"},{"id":59233,"name":"Scoot McNairy","character":"Wallace Keefe"},{"id":208296,"name":"Cal