('{"provider":"tmdb","externalId":"movie:141052","suggestedItemId":"d-tmdb-movie-141052","kind":"movie","type":"Filme","sourceUrl":"https://www.themoviedb.org/movie/141052","fetchedAt":"2026-10-03T18:02:39.545Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"Justice League","pt-BR":"Liga da Justiça"},"descriptions":{"en":"Fuelled by his restored faith in humanity and inspired by Superman''s selfless act, Bruce Wayne and Diana Prince assemble a team of metahumans consisting of Barry Allen, Arthur Curry and Victor Stone to face the catastrophic threat of Steppenwolf and the Parademons who are on the hunt for three Mother Boxes on Earth.","pt-BR":"Impulsionado pela restauração de sua fé na humanidade e inspirado pelo ato altruísta do Superman, Bruce Wayne convoca sua nova aliada Diana Prince para o combate contra um inimigo ainda maior, recém-despertado. Juntos, Batman e Mulher-Maravilha buscam e recrutam com agilidade um time de meta-humanos, mas mesmo com a formação da liga de heróis sem precedentes, poderá ser tarde demais para salvar o planeta de um catastrófico ataque."},"year":"2017","originalLanguage":"en","genres":["Action","Adventure","Science Fiction"],"cast":[{"id":880,"name":"Ben Affleck","character":"Batman / Bruce Wayne"},{"id":73968,"name":"Henry Cavill","character":"Superman / Clark Kent"},{"id":9273,"name":"Amy Adams","character":"Lois Lane"},{"id":90633,"name":"Gal Gadot","character":"Wonder Woman / Diana Prince"},{"id":132157,"name":"Ezra Miller","character":"The Flash / Barry Allen"},{"id":117642,"name":"Jason Momoa","character":"Aquaman / Arthur Curry"},{"id":1313559,"name":"Ray Fisher","character":"Cyborg / Victor Stone"},{"id":16940,"name":"Jeremy Irons","character":"Alfred"},{"id":2882,"name":"Diane Lane","character":"Martha Kent"},{"id":935,"name":"Connie Nielsen","character":"Queen Hippolyta"},{"id":18999,"name":"J.K. Simmons","character":"Comm