('{"provider":"tmdb","externalId":"movie:791373","suggestedItemId":"d-tmdb-movie-791373","kind":"movie","type":"Filme","sourceUrl":"https://www.themoviedb.org/movie/791373","fetchedAt":"2026-10-03T18:02:39.545Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"Zack Snyder''s Justice League","pt-BR":"Liga da Justiça de Zack Snyder"},"descriptions":{"en":"Determined to ensure Superman''s ultimate sacrifice was not in vain, Bruce Wayne aligns forces with Diana Prince with plans to recruit a team of metahumans to protect the world from an approaching threat of catastrophic proportions.","pt-BR":"Determinado a garantir que o sacrifício final do Superman não foi em vão, Bruce Wayne alinha forças com Diana Prince com planos de recrutar uma equipe de metahumanos para proteger o mundo de uma ameaça de proporções catastróficas que se aproxima."},"year":"2021","originalLanguage":"en","genres":["Action","Adventure","Fantasy"],"cast":[{"id":880,"name":"Ben Affleck","character":"Batman / Bruce Wayne"},{"id":73968,"name":"Henry Cavill","character":"Superman / Clark Kent"},{"id":90633,"name":"Gal Gadot","character":"Wonder Woman / Diana Prince"},{"id":1313559,"name":"Ray Fisher","character":"Cyborg / Victor Stone"},{"id":117642,"name":"Jason Momoa","character":"Aquaman / Arthur Curry"},{"id":132157,"name":"Ezra Miller","character":"The Flash / Barry Allen"},{"id":8785,"name":"Ciarán Hinds","character":"Steppenwolf (voice)"},{"id":9273,"name":"Amy Adams","character":"Lois Lane"},{"id":5293,"name":"Willem Dafoe","character":"Vulko"},{"id":16940,"name":"Jeremy Irons","character":"Alfred"},{"id":44735,"name":"Jesse Eisenberg","character":"Lex Luthor"},{"id":2882,"name":"Diane Lane","character":"Martha Kent"},{"id":935,"name":"Connie Nielsen","character":"Queen Hippolyta"},{"id":18999,"name":"J.K. Simmons","character":"Commissioner Gordon"},{"id":1279598,"name":"Ryan Zheng Kai","character"