('{"provider":"tmdb","externalId":"movie:298618","suggestedItemId":"d-tmdb-movie-298618","kind":"movie","type":"Filme","sourceUrl":"https://www.themoviedb.org/movie/298618","fetchedAt":"2026-10-03T18:02:39.545Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"The Flash","pt-BR":"The Flash"},"descriptions":{"en":"When his attempt to save his family inadvertently alters the future, Barry Allen becomes trapped in a reality in which General Zod has returned and there are no Super Heroes to turn to. In order to save the world that he is in and return to the future that he knows, Barry''s only hope is to race for his life. But will making the ultimate sacrifice be enough to reset the universe?","pt-BR":"Os mundos colidem quando Barry Allen usa seus superpoderes para viajar no tempo e mudar os acontecimentos do passado. Mas a tentativa de salvar sua família altera inadvertidamente o futuro."},"year":"2023","originalLanguage":"en","genres":["Action","Science Fiction","Adventure"],"cast":[{"id":132157,"name":"Ezra Miller","character":"Barry Allen / The Flash"},{"id":2542319,"name":"Sasha Calle","character":"Kara Zor-El / Supergirl"},{"id":2232,"name":"Michael Keaton","character":"Bruce Wayne / Batman"},{"id":335,"name":"Michael Shannon","character":"General Zod"},{"id":17402,"name":"Ron Livingston","character":"Henry Allen"},{"id":16971,"name":"Maribel Verdú","character":"Nora Allen"},{"id":1253355,"name":"Kiersey Clemons","character":"Iris West"},{"id":43202,"name":"Antje Traue","character":"Faora-Ul"},{"id":1660888,"name":"Saoirse-Monica Jackson","character":"Patty Spivot"},{"id":1727045,"name":"Rudy Mancuso","character":"Albert Desmond"},{"id":2651020,"name":"Ed Wade","character":"Court Reporter"},{"id":16940,"name":"Jeremy Irons","character":"Alfred Pennyworth"},{"id":7242,"name":"Temuera Morrison","character":"Thomas Curry"},{"id":145997,"name":"Sanjeev Bhaskar","characte