('{"provider":"tmdb","externalId":"movie:1726","suggestedItemId":"m-tmdb-movie-1726","kind":"movie","type":"Filme","sourceUrl":"https://www.themoviedb.org/movie/1726","fetchedAt":"2026-10-03T18:02:39.545Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"Iron Man","pt-BR":"Homem de Ferro"},"descriptions":{"en":"After being held captive in an Afghan cave, billionaire engineer Tony Stark creates a unique weaponized suit of armor to fight evil.","pt-BR":"Tony Stark é um industrial bilionário, que também é um brilhante inventor. Ao ser sequestrado ele é obrigado por terroristas a construir uma arma devastadora mas, ao invés disto, constrói uma armadura de alta tecnologia que permite que fuja de seu cativeiro. A partir de então ele passa a usá-la para combater o crime, sob o alter ego do Homem de Ferro."},"year":"2008","originalLanguage":"en","genres":["Action","Science Fiction","Adventure"],"cast":[{"id":3223,"name":"Robert Downey Jr.","character":"Tony Stark"},{"id":18288,"name":"Terrence Howard","character":"Rhodey"},{"id":1229,"name":"Jeff Bridges","character":"Obadiah Stane"},{"id":12052,"name":"Gwyneth Paltrow","character":"Pepper Potts"},{"id":57451,"name":"Leslie Bibb","character":"Christine Everhart"},{"id":17857,"name":"Shaun Toub","character":"Yinsen"},{"id":57452,"name":"Faran Tahir","character":"Raza"},{"id":9048,"name":"Clark Gregg","character":"Agent Coulson"},{"id":17200,"name":"Bill Smitrovich","character":"General Gabriel"},{"id":173810,"name":"Sayed Badreya","character":"Abu Bakaar"},{"id":6162,"name":"Paul Bettany","character":"Jarvis (voice)"},{"id":15277,"name":"Jon Favreau","character":"Hogan"},{"id":12708,"name":"Peter Billingsley","character":"William Ginter Riva"},{"id":40275,"name":"Tim Guinee","character":"Major Allen"},{"id":163671,"name":"Will Lyman","character":"Award Ceremony Narrator (voice)"},{"id":78299,"name":"Tom Morello","character":"Gu