('{"provider":"tmdb","externalId":"movie:1724","suggestedItemId":"m-tmdb-movie-1724","kind":"movie","type":"Filme","sourceUrl":"https://www.themoviedb.org/movie/1724","fetchedAt":"2026-10-03T18:02:39.545Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"The Incredible Hulk","pt-BR":"O Incrível Hulk"},"descriptions":{"en":"Scientist Bruce Banner scours the planet for an antidote to the unbridled force of rage within him: the Hulk. But when the military masterminds who dream of exploiting his powers force him back to civilization, he finds himself coming face to face with a new, deadly foe.","pt-BR":"Vivendo escondido e longe de Betty Ross, a mulher que ama, o cientista Bruce Banner busca um meio de retirar a radiação gama que está em seu sangue. Ao mesmo tempo ele precisa fugir da perseguição do general Ross, seu grande inimigo, e da máquina militar que tenta capturá-lo, na intenção de explorar o poder que faz com que Banner se transforme no Hulk."},"year":"2008","originalLanguage":"en","genres":["Science Fiction","Action","Adventure"],"cast":[{"id":819,"name":"Edward Norton","character":"Bruce Banner"},{"id":882,"name":"Liv Tyler","character":"Betty Ross"},{"id":3129,"name":"Tim Roth","character":"Emil Blonsky"},{"id":227,"name":"William Hurt","character":"General ''Thunderbolt'' Ross"},{"id":1462,"name":"Tim Blake Nelson","character":"Samuel Sterns"},{"id":15232,"name":"Ty Burrell","character":"Leonard"},{"id":68277,"name":"Christina Cabot","character":"Major Kathleen Sparr"},{"id":68278,"name":"Peter Mensah","character":"General Joe Greller"},{"id":19137,"name":"Lou Ferrigno","character":"Voice of The Incredible Hulk / Security Guard"},{"id":1215283,"name":"Paul Soles","character":"Stanley"},{"id":964764,"name":"Débora Nascimento","character":"Martina"},{"id":231,"name":"Greg Bryk","character":"Commando"},{"id":158459,"name":"Chris Owens","character":"Commando"},{"i