('{"provider":"tmdb","externalId":"movie:10138","suggestedItemId":"m-tmdb-movie-10138","kind":"movie","type":"Filme","sourceUrl":"https://www.themoviedb.org/movie/10138","fetchedAt":"2026-10-03T18:02:39.545Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"Iron Man 2","pt-BR":"Homem de Ferro 2"},"descriptions":{"en":"With the world now aware of his dual life as the armored superhero Iron Man, billionaire inventor Tony Stark faces pressure from the government, the press and the public to share his technology with the military. Unwilling to let go of his invention, Stark, with Pepper Potts and James ''Rhodey'' Rhodes at his side, must forge new alliances – and confront powerful enemies.","pt-BR":"Em um mundo ciente da existência do Homem de Ferro, o inventor bilionário Tony Stark sofre pressão de todos os lados para compartilhar sua tecnologia com as forças armadas. Ele resiste para divulgar os segredos de sua inigualável armadura, com medo de que estas informações caiam nas mãos erradas."},"year":"2010","originalLanguage":"en","genres":["Adventure","Action","Science Fiction"],"cast":[{"id":3223,"name":"Robert Downey Jr.","character":"Tony Stark"},{"id":12052,"name":"Gwyneth Paltrow","character":"Pepper Potts"},{"id":1896,"name":"Don Cheadle","character":"Lt. Col. James ''Rhodey'' Rhodes"},{"id":1245,"name":"Scarlett Johansson","character":"Natalie Rushman / Natasha Romanoff"},{"id":6807,"name":"Sam Rockwell","character":"Justin Hammer"},{"id":2295,"name":"Mickey Rourke","character":"Ivan Vanko"},{"id":2231,"name":"Samuel L. Jackson","character":"Nick Fury"},{"id":9048,"name":"Clark Gregg","character":"Agent Coulson"},{"id":21134,"name":"John Slattery","character":"Howard Stark"},{"id":52865,"name":"Garry Shandling","character":"Senator Stern"},{"id":6162,"name":"Paul Bettany","character":"Jarvis (voice)"},{"id":51072,"name":"Kate Mara","character":"U.S. Marshal"},{"id"