('{"provider":"tmdb","externalId":"movie:1771","suggestedItemId":"m-tmdb-movie-1771","kind":"movie","type":"Filme","sourceUrl":"https://www.themoviedb.org/movie/1771","fetchedAt":"2026-10-03T18:02:39.546Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"Captain America: The First Avenger","pt-BR":"Capitão América: O Primeiro Vingador"},"descriptions":{"en":"During World War II, Steve Rogers is a sickly man from Brooklyn who''s transformed into super-soldier Captain America to aid in the war effort. Rogers must stop the Red Skull – Adolf Hitler''s ruthless head of weaponry, and the leader of an organization that intends to use a mysterious device of untold powers for world domination.","pt-BR":"Durante a Segunda Guerra Mundial, Steve Rogers é um homem doente, do Brooklyn, que se transforma no super soldado Capitão América para ajudar nos esforços de guerra. Rogers deve parar o Caveira Vermelha, o implacável chefe de armas de Adolf Hitler e líder de uma organização que pretende usar um misterioso mecanismo de incalculáveis poderes para dominar o mundo."},"year":"2011","originalLanguage":"en","genres":["Action","Adventure","Science Fiction"],"cast":[{"id":16828,"name":"Chris Evans","character":"Captain America / Steve Rogers"},{"id":39459,"name":"Hayley Atwell","character":"Peggy Carter"},{"id":60898,"name":"Sebastian Stan","character":"James Buchanan ''Bucky'' Barnes"},{"id":2176,"name":"Tommy Lee Jones","character":"Colonel Chester Phillips"},{"id":1331,"name":"Hugo Weaving","character":"Johann Schmidt / Red Skull"},{"id":55470,"name":"Dominic Cooper","character":"Howard Stark"},{"id":30315,"name":"Richard Armitage","character":"Heinz Kruger"},{"id":2283,"name":"Stanley Tucci","character":"Dr. Abraham Erskine"},{"id":2231,"name":"Samuel L. Jackson","character":"Nick Fury"},{"id":13014,"name":"Toby Jones","character":"Dr. Arnim Zola"},{"id":2203,"name":"Neal McDonough",