('{"provider":"tmdb","externalId":"movie:76338","suggestedItemId":"m-tmdb-movie-76338","kind":"movie","type":"Filme","sourceUrl":"https://www.themoviedb.org/movie/76338","fetchedAt":"2026-10-03T18:02:39.546Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"Thor: The Dark World","pt-BR":"Thor: O Mundo Sombrio"},"descriptions":{"en":"Thor fights to restore order across the cosmos… but an ancient race led by the vengeful Malekith returns to plunge the universe back into darkness. Faced with an enemy that even Odin and Asgard cannot withstand, Thor must embark on his most perilous and personal journey yet, one that will reunite him with Jane Foster and force him to sacrifice everything to save us all.","pt-BR":"Thor precisa contar com a ajuda de seus companheiros e até de seu traiçoeiro irmão Loki em um plano audacioso para salvar o universo. Entretanto, os caminhos de Thor se cruzam com Jane Foster e, dessa vez, a vida dela está realmente em perigo."},"year":"2013","originalLanguage":"en","genres":["Action","Adventure","Fantasy"],"cast":[{"id":74568,"name":"Chris Hemsworth","character":"Thor"},{"id":524,"name":"Natalie Portman","character":"Jane Foster"},{"id":91606,"name":"Tom Hiddleston","character":"Loki"},{"id":2040,"name":"Christopher Eccleston","character":"Malekith"},{"id":4173,"name":"Anthony Hopkins","character":"Odin"},{"id":59817,"name":"Jaimie Alexander","character":"Sif"},{"id":69899,"name":"Zachary Levi","character":"Fandral"},{"id":56614,"name":"Ray Stevenson","character":"Volstagg"},{"id":13275,"name":"Tadanobu Asano","character":"Hogun"},{"id":17605,"name":"Idris Elba","character":"Heimdall"},{"id":14343,"name":"Rene Russo","character":"Frigga"},{"id":31164,"name":"Adewale Akinnuoye-Agbaje","character":"Algrim / Kurse"},{"id":52852,"name":"Kat Dennings","character":"Darcy Lewis"},{"id":1640,"name":"Stellan Skarsgård","character":"Erik Selvig"},{"id":2506