('{"provider":"tmdb","externalId":"movie:99861","suggestedItemId":"m-tmdb-movie-99861","kind":"movie","type":"Filme","sourceUrl":"https://www.themoviedb.org/movie/99861","fetchedAt":"2026-10-03T18:02:39.546Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"Avengers: Age of Ultron","pt-BR":"Vingadores: Era de Ultron"},"descriptions":{"en":"When Tony Stark tries to jumpstart a dormant peacekeeping program, things go awry and Earth’s Mightiest Heroes are put to the ultimate test as the fate of the planet hangs in the balance. As the villainous Ultron emerges, it is up to The Avengers to stop him from enacting his terrible plans, and soon uneasy alliances and unexpected action pave the way for an epic and unique global adventure.","pt-BR":"Ao tentar proteger o planeta de ameaças, Tony Stark constrói um sistema de inteligência artificial que cuidaria da paz mundial. O projeto acaba dando errado e gera o nascimento do Ultron. Com o destino da Terra em jogo, os Vingadores terão que se unir para mais uma vez salvar a raça humana da extinção."},"year":"2015","originalLanguage":"en","genres":["Action","Adventure","Science Fiction"],"cast":[{"id":3223,"name":"Robert Downey Jr.","character":"Tony Stark / Iron Man"},{"id":74568,"name":"Chris Hemsworth","character":"Thor"},{"id":103,"name":"Mark Ruffalo","character":"Bruce Banner / Hulk"},{"id":16828,"name":"Chris Evans","character":"Steve Rogers / Captain America"},{"id":1245,"name":"Scarlett Johansson","character":"Natasha Romanoff / Black Widow"},{"id":17604,"name":"Jeremy Renner","character":"Clint Barton / Hawkeye"},{"id":13548,"name":"James Spader","character":"Ultron (voice)"},{"id":2231,"name":"Samuel L. Jackson","character":"Nick Fury"},{"id":1896,"name":"Don Cheadle","character":"James Rhodes / War Machine"},{"id":27428,"name":"Aaron Taylor-Johnson","character":"Pietro Maximoff / Quicksilver"},{"id":550843,"name":"Elizabe