('{"provider":"tmdb","externalId":"movie:271110","suggestedItemId":"m-tmdb-movie-271110","kind":"movie","type":"Filme","sourceUrl":"https://www.themoviedb.org/movie/271110","fetchedAt":"2026-10-03T18:02:39.546Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"Captain America: Civil War","pt-BR":"Capitão América: Guerra Civil"},"descriptions":{"en":"Following the events of Age of Ultron, the collective governments of the world pass an act designed to regulate all superhuman activity. This polarizes opinion amongst the Avengers, causing two factions to side with Iron Man or Captain America, which causes an epic battle between former allies.","pt-BR":"Depois do ataque de Ultron, os políticos decidem controlar os Vingadores, já que suas ações afetam toda a humanidade. A decisão coloca o Capitão América em rota de colisão com o Homem de Ferro."},"year":"2016","originalLanguage":"en","genres":["Adventure","Action","Science Fiction"],"cast":[{"id":16828,"name":"Chris Evans","character":"Steve Rogers / Captain America"},{"id":3223,"name":"Robert Downey Jr.","character":"Tony Stark / Iron Man"},{"id":1245,"name":"Scarlett Johansson","character":"Natasha Romanoff / Black Widow"},{"id":60898,"name":"Sebastian Stan","character":"Bucky Barnes / Winter Soldier"},{"id":53650,"name":"Anthony Mackie","character":"Sam Wilson / Falcon"},{"id":1896,"name":"Don Cheadle","character":"Lieutenant James Rhodes / War Machine"},{"id":17604,"name":"Jeremy Renner","character":"Clint Barton / Hawkeye"},{"id":172069,"name":"Chadwick Boseman","character":"T''Challa / Black Panther"},{"id":6162,"name":"Paul Bettany","character":"Vision"},{"id":550843,"name":"Elizabeth Olsen","character":"Wanda Maximoff / Scarlet Witch"},{"id":22226,"name":"Paul Rudd","character":"Scott Lang / Ant-Man"},{"id":84247,"name":"Emily VanCamp","character":"Sharon Carter"},{"id":1136406,"name":"Tom Holland","character":"Pete