('{"provider":"tmdb","externalId":"movie:284054","suggestedItemId":"m-tmdb-movie-284054","kind":"movie","type":"Filme","sourceUrl":"https://www.themoviedb.org/movie/284054","fetchedAt":"2026-10-03T18:02:39.546Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"Black Panther","pt-BR":"Pantera Negra"},"descriptions":{"en":"King T''Challa returns home to the reclusive, technologically advanced African nation of Wakanda to serve as his country''s new leader. However, T''Challa soon finds that he is challenged for the throne by factions within his own country as well as without. Using powers reserved to Wakandan kings, T''Challa assumes the Black Panther mantle to join with ex-girlfriend Nakia, the queen-mother, his princess-kid sister, members of the Dora Milaje (the Wakandan ''special forces'') and an American secret agent, to prevent Wakanda from being dragged into a world war.","pt-BR":"O príncipe T''Challa retorna a Wakanda para ser coroado rei. Assumindo o manto de Pantera Negra, ele vai à caça de um vilão que roubou um precioso metal de seu país."},"year":"2018","originalLanguage":"en","genres":["Action","Adventure","Science Fiction"],"cast":[{"id":172069,"name":"Chadwick Boseman","character":"T''Challa / Black Panther"},{"id":135651,"name":"Michael B. Jordan","character":"Erik Killmonger"},{"id":1267329,"name":"Lupita Nyong''o","character":"Nakia"},{"id":82104,"name":"Danai Gurira","character":"Okoye"},{"id":7060,"name":"Martin Freeman","character":"Everett K. Ross"},{"id":206919,"name":"Daniel Kaluuya","character":"W''Kabi"},{"id":1083010,"name":"Letitia Wright","character":"Shuri"},{"id":1447932,"name":"Winston Duke","character":"M''Baku"},{"id":1225953,"name":"Sterling K. Brown","character":"N''Jobu"},{"id":9780,"name":"Angela Bassett","character":"Ramonda"},{"id":2178,"name":"Forest Whitaker","character":"Zuri"},{"id":1333,"name":"Andy Serkis","character":"Ulyss