('{"provider":"tmdb","externalId":"movie:363088","suggestedItemId":"m-tmdb-movie-363088","kind":"movie","type":"Filme","sourceUrl":"https://www.themoviedb.org/movie/363088","fetchedAt":"2026-10-03T18:02:39.546Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"Ant-Man and the Wasp","pt-BR":"Homem-Formiga e a Vespa"},"descriptions":{"en":"Just when his time under house arrest is about to end, Scott Lang once again puts his freedom at risk to help Hope van Dyne and Dr. Hank Pym dive into the quantum realm and try to accomplish, against time and any chance of success, a very dangerous rescue mission.","pt-BR":"Scott Lang lida com as consequências de suas escolhas tanto como super-herói quanto como pai. Enquanto tenta reequilibrar sua vida com suas responsabilidades como o Homem-Formiga, ele é confrontado por Hope van Dyne e Dr. Hank Pym com uma nova missão urgente. Scott deve mais uma vez vestir o uniforme e aprender a lutar ao lado da Vespa, trabalhando em conjunto para descobrir segredos do passado."},"year":"2018","originalLanguage":"en","genres":["Action","Adventure","Science Fiction"],"cast":[{"id":22226,"name":"Paul Rudd","character":"Scott Lang / Ant-Man"},{"id":19034,"name":"Evangeline Lilly","character":"Hope Van Dyne / Wasp"},{"id":3392,"name":"Michael Douglas","character":"Dr. Hank Pym"},{"id":1408809,"name":"Hannah John-Kamen","character":"Ava / Ghost"},{"id":79082,"name":"Randall Park","character":"Jimmy Woo"},{"id":1160,"name":"Michelle Pfeiffer","character":"Janet Van Dyne / Wasp"},{"id":2975,"name":"Laurence Fishburne","character":"Dr. Bill Foster"},{"id":454,"name":"Michael Peña","character":"Luis"},{"id":27740,"name":"Walton Goggins","character":"Sonny Burch"},{"id":21127,"name":"Bobby Cannavale","character":"Paxton"},{"id":20750,"name":"Judy Greer","character":"Maggie"},{"id":76126,"name":"T.I.","character":"Dave"},{"id":83854,"name":"David Dastmalchian