('{"provider":"tmdb","externalId":"movie:299537","suggestedItemId":"m-tmdb-movie-299537","kind":"movie","type":"Filme","sourceUrl":"https://www.themoviedb.org/movie/299537","fetchedAt":"2026-10-03T18:02:39.546Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"Captain Marvel","pt-BR":"Capitã Marvel"},"descriptions":{"en":"The story follows Carol Danvers as she becomes one of the universe’s most powerful heroes when Earth is caught in the middle of a galactic war between two alien races. Set in the 1990s, Captain Marvel is an all-new adventure from a previously unseen period in the history of the Marvel Cinematic Universe.","pt-BR":"Capitã Marvel, parte do exército de elite dos Kree, uma raça alienígena, encontra-se no meio de uma batalha entre seu povo e os Skrulls. Ao tentar impedir uma invasão de larga escala na Terra, em 1995, ela tem memórias recorrentes de uma outra vida, como Carol Danvers, agente da Força Aérea norte-americana. Com a ajuda de Nick Fury, Capitã Marvel precisa descobrir os segredos de seu passado e pôr um fim ao conflito intergalático com os Skrulls."},"year":"2019","originalLanguage":"en","genres":["Action","Adventure","Science Fiction"],"cast":[{"id":60073,"name":"Brie Larson","character":"Carol Danvers / Vers / Captain Marvel"},{"id":2231,"name":"Samuel L. Jackson","character":"Nick Fury"},{"id":77335,"name":"Ben Mendelsohn","character":"Talos / Keller"},{"id":9642,"name":"Jude Law","character":"Yon-Rogg"},{"id":516,"name":"Annette Bening","character":"Supreme Intelligence / Dr. Wendy Lawson"},{"id":938,"name":"Djimon Hounsou","character":"Korath"},{"id":72095,"name":"Lee Pace","character":"Ronan"},{"id":1360281,"name":"Lashana Lynch","character":"Maria Rambeau"},{"id":97576,"name":"Gemma Chan","character":"Minn-Erva"},{"id":9048,"name":"Clark Gregg","character":"Agent Coulson"},{"id":76618,"name":"Rune Temte","character":"Bron-Charr"},{"id":86