('{"provider":"tmdb","externalId":"movie:447365","suggestedItemId":"m-tmdb-movie-447365","kind":"movie","type":"Filme","sourceUrl":"https://www.themoviedb.org/movie/447365","fetchedAt":"2026-10-03T18:02:39.547Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"Guardians of the Galaxy Vol. 3","pt-BR":"Guardiões da Galáxia: Vol. 3"},"descriptions":{"en":"Peter Quill, still reeling from the loss of Gamora, must rally his team around him to defend the universe along with protecting one of their own. A mission that, if not completed successfully, could quite possibly lead to the end of the Guardians as we know them.","pt-BR":"Peter Quill, que ainda está se recuperando da perda de Gamora, tem que reunir a sua equipe para defender o universo e proteger um dos seus. Uma missão que, se não for concluída com sucesso, pode levar ao fim dos Guardiões como os conhecemos."},"year":"2023","originalLanguage":"en","genres":["Science Fiction","Adventure","Action"],"cast":[{"id":73457,"name":"Chris Pratt","character":"Peter Quill / Star-Lord"},{"id":8691,"name":"Zoe Saldaña","character":"Gamora"},{"id":543530,"name":"Dave Bautista","character":"Drax"},{"id":543261,"name":"Karen Gillan","character":"Nebula"},{"id":139820,"name":"Pom Klementieff","character":"Mantis"},{"id":12835,"name":"Vin Diesel","character":"Groot (voice)"},{"id":51329,"name":"Bradley Cooper","character":"Rocket (voice)"},{"id":51663,"name":"Sean Gunn","character":"Kraglin / Young Rocket (voice)"},{"id":105238,"name":"Chukwudi Iwuji","character":"The High Evolutionary"},{"id":93491,"name":"Will Poulter","character":"Adam Warlock"},{"id":2408703,"name":"Maria Bakalova","character":"Cosmo (voice)"},{"id":1133349,"name":"Elizabeth Debicki","character":"Ayesha"},{"id":16483,"name":"Sylvester Stallone","character":"Stakar Ogord"},{"id":1696434,"name":"Austin Freeman","character":"On-Set Groot / Phlektik Guard"},{"id":85096,