('{"provider":"tmdb","externalId":"tv:1412","suggestedItemId":"d-tmdb-tv-1412","kind":"tv","type":"Série","sourceUrl":"https://www.themoviedb.org/tv/1412","fetchedAt":"2026-10-03T18:02:39.547Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"Arrow","pt-BR":"Arqueiro"},"descriptions":{"en":"Spoiled billionaire playboy Oliver Queen is missing and presumed dead when his yacht is lost at sea. He returns five years later a changed man, determined to clean up the city as a hooded vigilante armed with a bow.","pt-BR":"Após um violento naufrágio, o playboy milionário Oliver Queen é dado como morto. Cinco anos depois, é resgatado de uma ilha do Pacífico e enviado de volta para Starling City, onde passa a agir como vigilante secreto."},"year":"2012","originalLanguage":"en","genres":["Crime","Drama","Action & Adventure"],"cast":[{"id":76110,"name":"Stephen Amell","character":"Oliver Queen / Green Arrow"},{"id":116774,"name":"David Ramsey","character":"John Diggle / Spartan"},{"id":53184,"name":"Rick Gonzalez","character":"Rene Ramirez / Wild Dog"},{"id":576474,"name":"Juliana Harkavy","character":"Dinah Drake / Black Canary"},{"id":968006,"name":"Katherine McNamara","character":"Mia Smoak / Blackstar"},{"id":33702,"name":"Ben Lewis","character":"Adult William Clayton"},{"id":1581190,"name":"Joseph David-Jones","character":"Connor Hawke"},{"id":55775,"name":"Katie Cassidy","character":"Laurel Lance / Black Canary"}],"episodeCount":170,"seasonCount":8,"releaseDate":"2012-10-10","posterURL":"https://image.tmdb.org/t/p/w500/u8ZHFj1jC384JEkTt3vNg1DfWEb.jpg","creators":[{"id":1216615,"name":"Andrew Kreisberg","roles":["Creator"]},{"id":88967,"name":"Greg Berlanti","roles":["Creator"]},{"id":171830,"name":"Marc Guggenheim","roles":["Creator"]}],"characters":[]},"publication":{"universe":"dc","artworkOnly":false,"existing":false}}'::jsonb),
