('{"provider":"tmdb","externalId":"tv:95057","suggestedItemId":"d-tmdb-tv-95057","kind":"tv","type":"Série","sourceUrl":"https://www.themoviedb.org/tv/95057","fetchedAt":"2026-10-03T18:02:39.547Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"Superman & Lois","pt-BR":"Superman e Lois"},"descriptions":{"en":"After years of facing megalomaniacal supervillains, monsters wreaking havoc on Metropolis, and alien invaders intent on wiping out the human race, The Man of Steel aka Clark Kent and Lois Lane come face to face with one of their greatest challenges ever: dealing with all the stress, pressures and complexities that come with being working parents in today''s society.","pt-BR":"Clark Kent, o Superman, maior herói do mundo, e sua companheira Lois Lane, uma famosa jornalista, se esforçam para lidar com o estresse e as complexidades cotidianas de serem pais que trabalham na sociedade contemporânea."},"year":"2021","originalLanguage":"en","genres":["Drama","Sci-Fi & Fantasy"],"cast":[{"id":78198,"name":"Tyler Hoechlin","character":"Clark Kent / Superman"},{"id":74577,"name":"Elizabeth Tulloch","character":"Lois Lane"},{"id":1393181,"name":"Alex Garfin","character":"Jordan Kent"},{"id":3136340,"name":"Michael Bishop","character":"Jonathan Kent"}],"episodeCount":53,"seasonCount":4,"releaseDate":"2021-02-23","posterURL":"https://image.tmdb.org/t/p/w500/vlv1gn98GqMnKHLSh0dNciqGfBl.jpg","creators":[{"id":88967,"name":"Greg Berlanti","roles":["Creator"]},{"id":209763,"name":"Todd Helbing","roles":["Creator"]}],"characters":[]},"publication":{"universe":"dc","artworkOnly":false,"existing":false}}'::jsonb),
('{"provider":"tmdb","externalId":"tv:110492","suggestedItemId":"d-tmdb-tv-110492","kind":"tv","type":"Série","sourceUrl":"https://www.themoviedb.org/tv/110492","fetchedAt":"2026-10-03T18:02:39.547Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"Peacemaker","pt-BR":"Pacificador"},"descriptions":{"en":"The continuing story of Peacemaker, a vainglorious superhero/supervillain who believes in peace at any cost — no matter how many people he has to kill. After a miraculous recovery from his duel with Bloodsport, Peacemaker soon discovers that his freedom comes at a price.","pt-BR":"A série explorará as origens do Pacificador, um homem que acredita na paz a qualquer custo - não importa quantas pessoas ele tenha que matar para obtê-la."},"year":"2022","originalLanguage":"en","genres":["Action & Adventure","Sci-Fi & Fantasy","Comedy"],"cast":[{"id":56446,"name":"John Cena","character":"Christopher ''Chris'' Smith / Peacemaker"},{"id":1075037,"name":"Danielle Brooks","character":"Leota Adebayo"},{"id":234934,"name":"Freddie Stroma","character":"Adrian Chase / Vigilante"},{"id":87165,"name":"Jennifer Holland","character":"Emilia Harcourt"},{"id":559457,"name":"Steve Agee","character":"John Economos"},{"id":81685,"name":"Frank Grillo","character":"Rick Flag Sr."},{"id":418,"name":"Robert Patrick","character":"August ''Auggie'' Smith / Blue Dragon"}],"episodeCount":16,"seasonCount":2,"releaseDate":"2022-01-13","posterURL":"https://image.tmdb.org/t/p/w500/yb4F1Oocq8GfQt6iIuAgYEBokhG.jpg","creators":[{"id":15218,"name":"James Gunn","roles":["Creator"]}],"characters":[]},"publication":{"universe":"dc","artworkOnly":false,"existing":false}}'::jsonb),
('{"provider":"tmdb","externalId":"tv:194764","suggestedItemId":"d-tmdb-tv-194764","kind":"tv","type":"Série","sourceUrl":"https://www.themoviedb.org/tv/194764","fetchedAt":"2026-10-03T18:02:39.547Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"The Penguin","pt-BR":"Pinguim"},"descriptions":{"en":"With the city in peril following the seawall''s collapse, Oswald \"Oz\" Cobb seeks to fill the power vacuum left by the death of Carmine Falcone and finally give his mother Francis the life he''s always promised. But first, Oz must confront his enemies and his own demoralizing reputation as \"the Penguin.\"","pt-BR":"Após a queda dos Carmines, Oswald “Oz” Cobb está pronto para assumir o controle de Gotham e dar à sua mãe a vida que ele sempre lhe prometeu. Mas primeiro, ele terá de enfrentar inimigos novos e antigos, além do seu tão odiado apelido – O Pinguim – que não tornará o caminho deste gangster tão fácil."},"year":"2024","originalLanguage":"en","genres":["Drama","Crime"],"cast":[{"id":72466,"name":"Colin Farrell","character":"Oz ''The Penguin'' Cobb"},{"id":204392,"name":"Cristin Milioti","character":"Sofia Falcone"},{"id":1761634,"name":"Rhenzy Feliz","character":"Victor Aguilar"},{"id":77013,"name":"Deirdre O''Connell","character":"Francis Cobb"},{"id":6574,"name":"Clancy Brown","character":"Salvatore Maroni"},{"id":37158,"name":"Carmen Ejogo","character":"Eve Karlo"},{"id":21041,"name":"Shohreh Aghdashloo","character":"Nadia Maroni"},{"id":51995,"name":"Theo Rossi","character":"Dr. Julian Rush"},{"id":50217,"name":"Michael Kelly","character":"Johnny Viti"}],"episodeCount":8,"seasonCount":1,"releaseDate":"2024-09-19","posterURL":"https://image.tmdb.org/t/p/w500/vOWcqC4oDQws1doDWLO7d3dh5qc.jpg","creators":[{"id":1223896,"name":"Lauren LeFranc","roles":["Creator"]}],"characters":[]},"publication":{"universe":"dc","artworkOnly":false,"existing":false}}'::jsonb),
