('{"provider":"tmdb","externalId":"tv:88329","suggestedItemId":"m-tmdb-tv-88329","kind":"tv","type":"Série","sourceUrl":"https://www.themoviedb.org/tv/88329","fetchedAt":"2026-10-03T18:02:39.547Z","attribution":{"name":"TMDB","url":"https://www.themoviedb.org","termsUrl":"https://developer.themoviedb.org/docs/faq"},"metadata":{"titles":{"en":"Hawkeye","pt-BR":"Gavião Arqueiro"},"descriptions":{"en":"Former Avenger Clint Barton has a seemingly simple mission: get back to his family for Christmas. Possible? Maybe with the help of Kate Bishop, a 22-year-old archer with dreams of becoming a superhero. The two are forced to work together when a presence from Barton’s past threatens to derail far more than the festive spirit.","pt-BR":"O ex-vingador Clint Barton tem uma missão aparentemente simples: voltar para sua família no Natal. Será possível? Talvez com a ajuda de Kate Bishop, uma arqueira de 22 anos que sonha em se tornar uma super-heroína. Os dois são forçados a trabalhar juntos quando uma presença do passado de Barton ameaça descarrilar muito mais do que o espírito festivo."},"year":"2021","originalLanguage":"en","genres":["Drama","Comedy","Action & Adventure"],"cast":[{"id":17604,"name":"Jeremy Renner","character":"Clint Barton / Hawkeye"},{"id":130640,"name":"Hailee Steinfeld","character":"Kate Bishop"},{"id":76855,"name":"Tony Dalton","character":"Jack Duquesne"},{"id":2880523,"name":"Alaqua Cox","character":"Maya Lopez"},{"id":1278528,"name":"Fra Fee","character":"Kazimierz ''Kazi'' Kazimierczak"},{"id":107810,"name":"Aleks Paunovic","character":"Ivan"},{"id":118762,"name":"Piotr Adamczyk","character":"Tomas"},{"id":21657,"name":"Vera Farmiga","character":"Eleanor Bishop"}],"episodeCount":6,"seasonCount":1,"releaseDate":"2021-11-24","posterURL":"https://image.tmdb.org/t/p/w500/ct5pNE5dDHryHLDnxyZPYcqO1sz.jpg","creators":[{"id":1757552,"name":"Jonathan Igla","roles":["Creator"]}],"characters":[]},"publication":{"universe":"marvel","artworkOnly":false,"existing"