('{"provider":"metron","externalId":"issue:158876","suggestedItemId":"d-watchmen","kind":"issue","type":"HQ","sourceUrl":"https://metron.cloud/issue/158876/","fetchedAt":"2026-10-03T18:02:39.549Z","attribution":{"name":"Metron contributors","url":"https://metron.cloud","termsUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},"metadata":{"titles":{"pt-BR":"Watchmen: DC Compact Comics #1","en":"Watchmen: DC Compact Comics Edition #1"},"descriptions":{"pt-BR":"Edição DC Compact Comics que reúne Watchmen #1–12, a história completa.","en":"Graphic novels to read anywhere: DC Compact Comics collect DC’s bestselling, most iconic stories in a new size! In an alternate world where the mere presence of American superheroes changed history, the US won the Vietnam War, Nixon is still president and the cold war is in full effect! Considered the greatest graphic novel in the history of the medium, WATCHMEN begins as a murder mystery but soon unfolds into a planet-altering conspiracy. A group of reunited heroes: Rorschach, Nite Owl, Silk Spectre, Dr. Manhattan and Ozymandias, must test the limits of their convictions and ask themselves where the true line is between good and evil. Collects Watchmen #1-12, the complete story."},"year":"2024","releaseDate":"2024-06-04","coverDate":"2024-08-01","originalLanguage":"en","publisher":{"id":2,"name":"DC Comics"},"format":"Trade Paperback","isbn":"9781779527325","artworkOnly":true,"posterURL":"https://static.metron.cloud/media/issue/2025/12/23/1e935b508ec9d1fe06886f283bff88e67557.jpg.webp","pageCount":420,"series":{"id":14273,"title":"Watchmen: DC Compact Comics Edition","year":2024,"number":"1"},"creators":[{"id":63,"name":"Alan Moore","roles":["Writer"]},{"id":286,"name":"Dave Gibbons","roles":["Artist","Cover"]},{"id":2591,"name":"John Higgins","roles":["Colorist"]},{"id":59,"name":"Marie Javins","roles":["Editor In Chief"]}],"characters":[{"id":2384,"name":"Captain Metropolis"},{"id":258,"name":"Comedian"},{"id":269,"name":"Doctor