('{"provider":"metron","externalId":"issue:123899","suggestedItemId":"d-crise","kind":"issue","type":"HQ","sourceUrl":"https://metron.cloud/issue/123899/","fetchedAt":"2026-10-03T18:02:39.549Z","attribution":{"name":"Metron contributors","url":"https://metron.cloud","termsUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},"metadata":{"titles":{"pt-BR":"Crise nas Infinitas Terras: Edição Absoluta #1","en":"Crisis on Infinite Earths The Absolute Edition #1"},"descriptions":{"pt-BR":"Edição Absolute que reúne a minissérie Crise nas Infinitas Terras #1–12 e material complementar.","en":"Worlds lived. Worlds died. And the DC Universe was never the same! In 1985, DC Comics dramatically altered comics'' original universe with CRISIS ON INFINITE EARTHS, a 12-issue series that rocked the comics community, tragically dooming some of DC''s most beloved characters and drastically altering others. Written by Marv Wolfman and pencilled by George Pérez, with inks by Dick Giordano, Jerry Ordway and Mike DeCarlo, CRISIS ON INFINITE EARTHS finds the alternate worlds that once were a hallmark of the DC Universe under siege by a mysterious force powerful enough to wipe out the lives of billions. Now this landmark series gets the star treatment in CRISIS ON INFINITE EARTHS: THE ABSOLUTE EDITION — an over-sized slipcase set containing two hardcover books. The 368-page Book One includes the full 12-issue maxi-series (which was painstakingly restored and meticulously recolored in 1998), with an introduction by Marv Wolfman, afterword by Dick Giordano, and creator bios. George Pérez provides all-new art for the dust-jacket. (Please note that the Monitor Tapes section from issue #10 will be shot from the original art for this issue and represented in its original form.) The 96-page Book Two contains a compendium featuring the full behind-the-scenes story on the years-long making of the maxi-series complete with memos, notes, original plots and commentary from Marv Wolfman and Jerry Ordway; The Official Crisis on Infinite Earths Index and The Official Crisis on Infinite Earths Crossover Index being reprinted for the very first time, completely updated; a look into post-Crisis events and aftermath stories, how the Superboy/Legion conundrum was solved, and a look at the 20th anniversary of this seminal event. George Pérez provides all-new art for the dust-jacket."},"year":"2005","releaseDate":"2005-11-30","coverDate":"2005-11-01","originalLanguage":"en","publisher":{"id":2,"name":"DC Comics"},"format":"Hardcover","isbn":"9781401207120","artworkOnly":true,"posterURL":"https://static.metron.cloud/media/issue/2024/07/07/704430-31667_20060720050750_large.jpg","pageCount":368,"series":{"id":7966,"title":"Crisis on Infinite Earths The Absolute Edition","year":2005,"number":"1"},"creators":[{"id":1309,"name":"Anthony Tollin","roles":["Colorist"]},{"id":1059,"name":"Carl Gafford","roles":["Colorist"]},{"id":1148,"name":"Dan DiDio","roles":["Executive Editor"]},{"id":399,"name":"Dick Giordano","roles":["Inker"]},{"id":44,"name":"George Pérez","roles":["Penciller","Cover"]},{"id":334,"name":"Jerry Ordway","roles":["Inker"]},{"id":317,"name":"John Costanza","roles":["Letterer"]},{"id":34,"name":"Marv Wolfman","roles":["Writer","Editor"]},{"id":2863,"name":"Mike DeCarlo","roles":["Inker"]},{"id":135,"name":"Paul Levitz","roles":["President","Publisher"]},{"id":1311,"name":"Robert Greenberger","roles":["Collection Editor"]},{"id":1268,"name":"Tom McCraw","roles":["Colorist"]},{"id":1564,"name":"Tom Ziuko","roles":["Colorist"]}],"characters":[{"id":2612,"name":"Ace Morgan"},{"id":105,"name":"Adam Strange"},{"id":2219,"name":"Air Wave"},{"id":1280,"name":"Alanna Strange"},{"id":2814,"name":"Alex Luthor"},{"id":261,"name":"Alfred Pennyworth"},{"id":1144,"name":"Amethyst (DC)"},{"id":1538,"name":"Animal Man"},{"id":3561,"name":"Anthro"},{"id":2645,"name":"Anti-Monitor"},{"id":417,"name":"Aquagirl (Tula)"},{"id":86,"name":"Aquaman"},{"id":1636,"name":"Arion"},{"id":13