('{"provider":"metron","externalId":"issue:107214","suggestedItemId":"d-metron-issue-107214","kind":"issue","type":"HQ","sourceUrl":"https://metron.cloud/issue/107214/","fetchedAt":"2026-10-03T18:02:39.549Z","attribution":{"name":"Metron contributors","url":"https://metron.cloud","termsUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},"metadata":{"titles":{"pt-BR":"Batman: O Cavaleiro das Trevas #1","en":"Batman: The Dark Knight #1"},"descriptions":{"pt-BR":"Após dez anos afastado, Bruce Wayne volta a agir como Batman em uma Gotham dominada pelo crime e ameaçada pela gangue dos Mutantes.","en":"Batman: The Dark Knight Returns is set 20 years in the future. In the absence of superheroes, criminals run amok, and a gang called the Mutants terrorize Gotham City. Bruce Wayne has been retired from crime fighting for ten years following the death of Jason Todd, the second Robin. Despite Wayne''s funding of the rehabilitation of Harvey Dent (Two-Face), Dent returns to crime. Bruce, overcome with the grief of what Gotham has become, as well as being unable to resist his true identity as Batman, dons the costume again and apprehends Dent, and the populace debates whether Batman is a savior or a threat to society."},"year":"1986","releaseDate":"1986-03-20","coverDate":"1986-02-01","originalLanguage":"en","publisher":{"id":2,"name":"DC Comics"},"format":"Limited Series","posterURL":"https://static.metron.cloud/media/issue/2024/01/28/7913a065c61348009583e5d1eed26d25.jpg","pageCount":52,"series":{"id":6891,"title":"Batman: The Dark Knight","year":1986,"number":"1"},"creators":[{"id":128,"name":"Dennis O''Neil","roles":["Editor"]},{"id":399,"name":"Dick Giordano","roles":["Editor"]},{"id":48,"name":"Frank Miller","roles":["Writer","Penciller","Cover"]},{"id":317,"name":"John Costanza","roles":["Letterer"]},{"id":49,"name":"Klaus Janson","roles":["Inker"]},{"id":4062,"name":"Lynn Varley","roles":["Colorist","Cover"]}],"characters":[{"id":25582,"name":"Abner"},{"id":261,"name"