('{"provider":"metron","externalId":"issue:107217","suggestedItemId":"d-metron-issue-107217","kind":"issue","type":"HQ","sourceUrl":"https://metron.cloud/issue/107217/","fetchedAt":"2026-10-03T18:02:39.549Z","attribution":{"name":"Metron contributors","url":"https://metron.cloud","termsUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},"metadata":{"titles":{"pt-BR":"Batman: O Cavaleiro das Trevas #4","en":"Batman: The Dark Knight #4"},"descriptions":{"pt-BR":"Na conclusão da minissérie, Batman e Superman se enfrentam em um conflito que coloca seus caminhos em choque.","en":"The World''s Greatest Detective. The Man of Steel. The World''s Finest. Fight of the Century. The Dark Knights greatest tale reaches its finale."},"year":"1986","releaseDate":"","coverDate":"1986-09-01","originalLanguage":"en","publisher":{"id":2,"name":"DC Comics"},"format":"Limited Series","posterURL":"https://static.metron.cloud/media/issue/2024/01/28/21af89b7da624d4db0c2bf2aae4be625.jpeg","pageCount":52,"series":{"id":6891,"title":"Batman: The Dark Knight","year":1986,"number":"4"},"creators":[{"id":128,"name":"Dennis O''Neil","roles":["Editor"]},{"id":399,"name":"Dick Giordano","roles":["Editor"]},{"id":48,"name":"Frank Miller","roles":["Writer","Penciller","Cover"]},{"id":317,"name":"John Costanza","roles":["Letterer"]},{"id":49,"name":"Klaus Janson","roles":["Inker"]},{"id":4062,"name":"Lynn Varley","roles":["Colorist","Cover"]}],"characters":[{"id":261,"name":"Alfred Pennyworth"},{"id":12,"name":"Batman"},{"id":4103,"name":"Carrie Kelley"},{"id":77,"name":"Catwoman"},{"id":25587,"name":"Ellen Yindel"},{"id":542,"name":"Green Arrow"},{"id":82,"name":"James Gordon"},{"id":25584,"name":"Lola Chong"},{"id":24681,"name":"Ronald Reagan"},{"id":16894,"name":"Stan Merkel"},{"id":13,"name":"Superman"}]},"publication":{"universe":"dc","artworkOnly":false,"issue":{"id":107217,"number":"4","universe":"dc","seriesID":6891,"series":"Batman: The Dark Knight","seriesPT":"Batman: O Cavaleiro das Trev