('{"provider":"metron","externalId":"issue:53175","suggestedItemId":"d-metron-issue-53175","kind":"issue","type":"HQ","sourceUrl":"https://metron.cloud/issue/53175/","fetchedAt":"2026-10-03T18:02:39.549Z","attribution":{"name":"Metron contributors","url":"https://metron.cloud","termsUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},"metadata":{"titles":{"pt-BR":"Grandes Astros: Superman #1","en":"All Star Superman #1"},"descriptions":{"pt-BR":"Ao salvar exploradores na superfície do Sol, Superman recebe uma carga extraordinária de radiação solar. Lex Luthor parece ter previsto as consequências.","en":"Grant Morrison and artist Frank Quitely - the acclaimed team behind JLA: EARTH 2 - are at it once again, this time to strip down the Man of Steel to his timeless, essential elements. The series touches on all the classic aspects of the Superman mythology, starting with a daring rescue of a doomed group of helionauts on the surface of the sun. The massive amounts of solar radiation affect Superman in a way no one could possibly anticipate - except Lex Luthor!"},"year":"2005","releaseDate":"2005-11-16","coverDate":"2006-01-01","originalLanguage":"en","publisher":{"id":2,"name":"DC Comics"},"format":"Limited Series","upc":"76194124873800111","posterURL":"https://static.metron.cloud/media/issue/2022/11/20/all-star-superman-1.jpg","pageCount":44,"series":{"id":3988,"title":"All Star Superman","year":2006,"number":"1"},"creators":[{"id":1262,"name":"Bob Schreck","roles":["Editor"]},{"id":4103,"name":"Brandon Montclare","roles":["Assistant Editor"]},{"id":2594,"name":"Chip Kidd","roles":["Logo Design"]},{"id":91,"name":"Frank Quitely","roles":["Penciller","Cover"]},{"id":97,"name":"Grant Morrison","roles":["Writer"]},{"id":1174,"name":"Jamie Grant","roles":["Inker","Colorist"]},{"id":123,"name":"Neal Adams","roles":["Cover"]},{"id":627,"name":"Phil Balsman","roles":["Letterer"]}],"characters":[{"id":17032,"name":"Agatha"},{"id":850,"name":"Cat Grant"},{"id":102,"name":"