('{"provider":"metron","externalId":"issue:53178","suggestedItemId":"d-metron-issue-53178","kind":"issue","type":"HQ","sourceUrl":"https://metron.cloud/issue/53178/","fetchedAt":"2026-10-03T18:02:39.549Z","attribution":{"name":"Metron contributors","url":"https://metron.cloud","termsUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},"metadata":{"titles":{"pt-BR":"Grandes Astros: Superman #4","en":"All Star Superman #4"},"descriptions":{"pt-BR":"Jimmy Olsen assume por um dia a direção do P.R.O.J.E.C.T. e recebe uma ordem inesperada: deter um Superman fora de controle.","en":"Jimmy Olsen, the Daily Planet''s \"Mister Action,\" is young, brilliant, and reckless! For this week''s story he must become the director-for-a-day of P.R.O.J.E.C.T. With top agents assigned to protect him, he''s looking forward to an easy day of jet-setting and international liaisons all in the name of scientific discovery. Instead, P.R.O.J.E.C.T. receives a terrifying directive-to take down a rogue Superman!"},"year":"2006","releaseDate":"2006-06-21","coverDate":"2006-07-01","originalLanguage":"en","publisher":{"id":2,"name":"DC Comics"},"format":"Limited Series","upc":"76194124873800411","posterURL":"https://static.metron.cloud/media/issue/2022/11/20/all-star-superman-4.jpg","pageCount":36,"series":{"id":3988,"title":"All Star Superman","year":2006,"number":"4"},"creators":[{"id":1262,"name":"Bob Schreck","roles":["Editor"]},{"id":4103,"name":"Brandon Montclare","roles":["Assistant Editor"]},{"id":91,"name":"Frank Quitely","roles":["Penciller","Cover"]},{"id":97,"name":"Grant Morrison","roles":["Writer"]},{"id":1174,"name":"Jamie Grant","roles":["Inker","Colorist"]},{"id":627,"name":"Phil Balsman","roles":["Letterer"]}],"characters":[{"id":17032,"name":"Agatha"},{"id":102,"name":"Jimmy Olsen"},{"id":17033,"name":"Leo Quintum"},{"id":2030,"name":"Lucy Lane"},{"id":484,"name":"Perry White"},{"id":13,"name":"Superman"}]},"publication":{"universe":"dc","artworkOnly":false,"issue":{"id":53178,